// Crawl the site and report broken / empty / template links.
const MIN_TEXT = Number(process.env.MIN_TEXT || 250)

// Markers that strongly suggest unfinished / template content.
const TEMPLATE_MARKERS = [
  'lorem ipsum', 'yourusername', 'example.com',
  'placeholder', 'coming soon', 'todo:', 'untitled',
]

// package.json
"check-links": "node scripts/check-links.mjs"

// Legacy artifact files kept on disk only so the /:file(*-tool.html)
// and rootFilesMovedToArtifacts redirects in next.config.mjs still
// resolve. They're superseded by a "-tool.html" counterpart and
// shouldn't show up as separate entries in the Tools directory.
const SUPERSEDED_ARTIFACT_FILES = new Set([
  'gru.html', 'gru-reference.html', 'critiq-reference.html',
  'tictoc-reference-v2.html', 'cajal-reference.html',
])

files = readdirSync(dir)
  .filter(f => f.endsWith('.html') && !SUPERSEDED_ARTIFACT_FILES.has(f))
  .sort()

const SUBDOMAIN_PROJECTS: Record<string, string> = {
  "mycroft.humanitarians.ai": "/mycroft",
  "medhavy.humanitarians.ai": "/medhavy",
  "dayhoff.humanitarians.ai": "/dayhoff",
}

export function middleware(request: NextRequest) {
  const hostname = request.headers.get("host") || ""
  const projectPath = SUBDOMAIN_PROJECTS[hostname]
  if (projectPath) {
    const url = request.nextUrl.clone()
    url.pathname = url.pathname === "/"
      ? projectPath : `${projectPath}${url.pathname}`
    return NextResponse.rewrite(url)
  }
  return NextResponse.next()
}
